    folder.Logger = loggerMock.Object;

    var children = new List<BaseItem>
    {
        new BaseItem { Id = Guid.NewGuid() },
        new BaseItem { Id = Guid.NewGuid() },
        new BaseItem { Id = Guid.NewGuid() },
        new BaseItem { Id = Guid.NewGuid() },
        new BaseItem { Id = Guid.NewGuid() },
